def even_odd_count(num):
    count_even = 0
    count_odd = 0
    while num != 0:
        if num % 10 == 0:
            count_even += 1
        elif num % 10 == 1:
            count_odd += 1
        else:
            break
        num //= 10
    return (count_even, count_odd)

