def solve(s):
  res = ''
  for i in range(len(s)):
    if s[i].isalpha():
      res += chr(32 + ord(s[i]) - ord('A'))
    else:
      res += s[i]
  return (res)

import hashlib
def string_to_md5(text):
  if not text:
    return None
  else:
    return hashlib.md5(text.encode()).hexdigest()

